mapper.insert:
/* IInqryMapper.insertInqry */
INSERT INTO apt_board_post (
                             post_no          /* 게시글번호 */
                           , board_no         /* 게시판번호 */
                           , ttl              /* 제목 */
                           , cn               /* 내용 */
                           , wrtr_id          /* 작성자ID */
                           , prrt_cd          /* 문의유형코드 */
                           , reg_dttm         /* 등록일시 */
                           , mdf_dttm         /* 수정일시 */
                           , inq_cnt          /* 조회수 */
                           , del_yn           /* 삭제여부 */
                           , atch_file_id     /* 첨부파일ID */
                           , opn_yn           /* 공개여부 */
) VALUES (
           'IQ' || TO_CHAR(SYSDATE, 'YYMMDDHH24MISS')
         , #{boardNo}
         , #{ttl}
         , #{cn}
         , #{wrtrId}
         , #{prrtCd}
         , SYSDATE
         , NULL
         , 0
         , 'N'
         , #{atchFileId}
         , #{opnYn}
         )

mapper.update:
/* IInqryMapper.deleteInqry */
UPDATE apt_board_post abp
SET abp.del_yn = 'Y'
  , abp.mdf_dttm = SYSDATE
WHERE abp.post_no = #{postNo}
  AND abp.wrtr_id = #{wrtrId}
  AND EXISTS (
    SELECT 1
    FROM apt_board_instance abi
    WHERE abi.board_no = abp.board_no
      AND abi.apt_cmplex_no = #{aptCmplexNo}
      AND abi.board_ty_cd = #{boardTyCd}
      AND abi.use_yn = 'Y'
)

mapper.select:
/* IInqryMapper.getTotalCount */
SELECT COUNT(*)
FROM apt_board_post abp
         JOIN apt_board_instance abi
              ON abp.board_no = abi.board_no
WHERE abi.apt_cmplex_no = #{aptCmplexNo}
  AND abi.board_ty_cd = #{boardTyCd}
  AND abi.use_yn = 'Y'
  AND abp.del_yn = 'N'
  AND abp.wrtr_id = #{wrtrId}

mapper.update:
        /* IInqryMapper.updateInqry */

        UPDATE apt_board_post
        SET ttl       = #{dto.ttl}
          , cn        = #{dto.cn}
          , prrt_cd   = #{dto.prrtCd}
          , opn_yn    = #{dto.opnYn}
          , mdf_dttm  = SYSDATE
        WHERE post_no   = #{dto.postNo}
          AND wrtr_id   = #{userId}
          AND del_yn    = 'N'
